class ClientEncryption { ClientEncryption(opts: ClientEncryptionOpts); // The "Create Encrypted Collection" helper is a convenience function wrapping CreateCollection. It will // create a collection with encrypted fields, automatically allocating and assigning new data encryption // keys. It returns a handle to the new collection, as well as a document consisting of the generated // "encryptedFields" options. Refer to "Create Encrypted Collection Helper" createEncryptedCollection(database: Database, collName: string, collOpts, kmsProvider: KMSProvider, masterKey: Optional<Document>): [Collection, Document]; // Creates a new key document and inserts into the key vault collection. // Returns the _id of the created document as a UUID (BSON binary subtype 0x04). createDataKey(kmsProvider: KMSProvider, opts: DataKeyOpts | null): Binary; // Decrypts multiple data keys and (re-)encrypts them with a new masterKey, or with their current masterKey if a new one is not given. // The updated fields of each rewrapped data key is updated in the key vault collection as part of a single bulk write operation. // If no data key matches the given filter, no bulk write operation is executed. // Returns a RewrapManyDataKeyResult. rewrapManyDataKey(filter: Document, opts: RewrapManyDataKeyOpts | null): RewrapManyDataKeyResult; // Removes the key document with the given UUID (BSON binary subtype 0x04) from the key vault collection. // Returns the result of the internal deleteOne() operation on the key vault collection. deleteKey(id: Binary): DeleteResult; // Finds a single key document with the given UUID (BSON binary subtype 0x04). // Returns the result of the internal find() operation on the key vault collection. getKey(id: Binary): Optional<Document>; // Finds all documents in the key vault collection. // Returns the result of the internal find() operation on the key vault collection. getKeys(): Iterable<Document>; // Adds a keyAltName to the keyAltNames array of the key document in the key vault collection with the given UUID (BSON binary subtype 0x04). // Returns the previous version of the key document. addKeyAltName(id: Binary, keyAltName: String): Optional<Document>; // Removes a keyAltName from the keyAltNames array of the key document in the key vault collection with the given UUID (BSON binary subtype 0x04). // Returns the previous version of the key document. removeKeyAltName(id: Binary, keyAltName: String): Optional<Document>; // Returns a key document in the key vault collection with the given keyAltName. getKeyByAltName(keyAltName: String): Optional<Document>; // Encrypts a BsonValue with a given key and algorithm. // Returns an encrypted value (BSON binary of subtype 6). The underlying implementation MAY return an error for prohibited BSON values. encrypt(value: BsonValue, opts: EncryptOpts): Binary; // encryptExpression encrypts a Match Expression or Aggregate Expression to query a range index. // `expr` is expected to be a BSON document of one of the following forms: // 1. A Match Expression of this form: // {$and: [{<field>: {$gt: <value1>}}, {<field>: {$lt: <value2> }}]} // 2. An Aggregate Expression of this form: // {$and: [{$gt: [<fieldpath>, <value1>]}, {$lt: [<fieldpath>, <value2>]}] // $gt may also be $gte. $lt may also be $lte. // Only supported when queryType is "range" and algorithm is "Range". encryptExpression(expr: Document, opts: EncryptOpts): Document; // Decrypts an encrypted value (BSON binary of subtype 6). // Returns the original BSON value. decrypt(value: Binary): BsonValue; // Implementation details. private mongocrypt_t libmongocrypt_handle; private MongoClient keyvault_client;
} interface ClientEncryptionOpts { keyVaultClient: MongoClient; keyVaultNamespace: String; kmsProviders: KMSProviders; tlsOptions?: KMSProvidersTLSOptions; // Maps KMS provider to TLS options.
}; interface KMSProvidersTLSOptions { // Map the KMS providers to a set of TLS options [provider: KMSProvider]: TLSOptionsMap;
}; The ClientEncryption encapsulates explicit operations on a key vault collection that cannot be done directly on a MongoClient. Similar to configuring auto encryption on a MongoClient, it is constructed with a MongoClient (to a MongoDB cluster containing the key vault collection), KMS provider configuration, keyVaultNamespace, and tlsOptions. It provides an API for explicitly encrypting and decrypting values, and managing data keys in the key vault collection. See Why do we have a separate top level type for ClientEncryption? and Why do we need to pass a client to create a ClientEncryption? When implementing behavior and error handling for key vault functions, Drivers SHOULD assume the presence of a unique index in the key vault collection on the keyAltNames field with a partial index filter for only documents where keyAltNames exists when implementing behavior of key management functions. Drivers MAY choose to not validate or enforce the existence of the unique index, but MUST still be capable of handling errors that such a unique index may yield. See Why aren't we creating a unique index in the key vault collection?

