accounts = client.db.accounts
results = accounts.aggregate([ { "$lookup": { "from": "people", "pipeline": [ { "$match": { "ssn": "457-55-5462" } } ], "as": "person" }
]) # Raises an error print (next(results)["person"]["ssn"]) In this case, the user should use explicit encryption on a client configured to bypass auto encryption. (Note, automatic decryption still occurs). opts = AutoEncryptionOpts ( key_vault_namespace="keyvault.datakeys", kms_providers=kms, bypass_auto_encryption=True)
client = MongoClient(auto_encryption_opts=opts) opts = ClientEncryptionOpts ( key_vault_client=client, key_vault_namespace="keyvault.datakeys", kms_providers=kms, bypass_auto_encryption=True)
client_encryption = ClientEncryption(opts) accounts = client.db.accounts
results = accounts.aggregate([ { "$lookup": { "from": "people", "pipeline": [ { "$match": { "ssn": client_encryption.encrypt("457-55-5462", EncryptOpts(key_alt_name="ssn", algorithm="AEAD_AES_256_CBC_HMAC_SHA_512-Deterministic")) } } ], "as": "person" }
]) # Throws an exception print (next(results)["person"]["ssn"])

