} interface CommandFailedEvent { /** * Returns the execution time of the event in the highest possible resolution for the platform. * The calculated value MUST be the time to send the message and receive the reply from the server * and MAY include BSON serialization and/or deserialization. The name can imply the units in which the * value is returned, i.e. durationMS, durationNanos. */ duration: Int64; /** * Returns the command name. */ commandName: String; /** * Returns the database name. */ databaseName: String; /** * Returns the failure. Based on the language, this SHOULD be a message string, exception * object, or error document. */ failure: String,Exception,Document; /** * Returns the client generated request id. */ requestId: Int64; /** * Returns the driver generated operation id. This is used to link events together such * as bulk write operations. OPTIONAL. */ operationId: Int64; /** * Returns the connection id for the command. For languages that do not have this, * this MUST return the driver equivalent which MUST include the server address and port. * The name of this field is flexible to match the object that is returned from the driver. */ connectionId: ConnectionId; /** * Returns the server connection id for the command. The server connection id is distinct from * the connection id and is returned by the hello or legacy hello response as "connectionId" * from the server on 4.2+. Drivers MUST use an Int64 to represent the server connection ID value. */ serverConnectionId: Optional<Int64>; /** * Returns the service id for the command when the driver is in load balancer mode. * For drivers that wish to include this in their ConnectionId object, this field is * optional. */ serviceId: Optional<ObjectId>;
}

