This specification defines 9 main events that MUST be published in the scenarios described. 6 of these events are the core behaviour within the cluster lifecycle, and the remaining 3 server heartbeat events are fired from the server monitor and follow the guidelines for publishing in the command monitoring specification. Events that MUST be published (with their conditions) are as follows. Event Type Condition TopologyOpeningEvent When a topology description is initialized - this MUST be the first SDAM event fired. ServerOpeningEvent Published when the server description is instantiated with its defaults, and MUST be the first operation to happen after the defaults are set. This is before the Monitor is created and the Monitor socket connection is opened. ServerDescriptionChangedEvent When the old server description is not equal to the new server description TopologyDescriptionChangedEvent When the old topology description is not equal to the new topology description. ServerClosedEvent Published when the server monitor's connection is closed and the server is shutdown. TopologyClosedEvent When a topology is shut down - this MUST be the last SDAM event fired. ServerHeartbeatStartedEvent Published when the server monitor sends its hello or legacy hello call to the server. When the monitor is creating a new connection, this event MUST be published just before the socket is created. ServerHeartbeatSucceededEvent Published on successful completion of the server monitor's hello or legacy hello call. ServerHeartbeatFailedEvent Published on failure of the server monitor's hello or legacy hello call, either with an ok: 0 result or a socket exception from the connection. /** * Published when server description changes, but does NOT include changes to the RTT. */
interface ServerDescriptionChangedEvent { /** * Returns the address (host/port pair) of the server. */ address: ServerAddress; /** * Returns a unique identifier for the topology. */ topologyId: Object; /** * Returns the previous server description. */ previousDescription: ServerDescription; /** * Returns the new server description. */ newDescription: ServerDescription;
} /** * Published when server is initialized. */
interface ServerOpeningEvent { /** * Returns the address (host/port pair) of the server. */ address: ServerAddress; /** * Returns a unique identifier for the topology. */ topologyId: Object;
} /** * Published when server is closed. */
interface ServerClosedEvent { /** * Returns the address (host/port pair) of the server. */ address: ServerAddress; /** * Returns a unique identifier for the topology. */ topologyId: Object;
} /** * Published when topology description changes. */
interface TopologyDescriptionChangedEvent { /** * Returns a unique identifier for the topology. */ topologyId: Object; /** * Returns the old topology description. */ previousDescription: TopologyDescription; /** * Returns the new topology description. */ newDescription: TopologyDescription;
} /** * Published when topology is initialized. */
interface TopologyOpeningEvent { /** * Returns a unique identifier for the topology. */ topologyId: Object;
} /** * Published when topology is closed. */
interface TopologyClosedEvent { /** * Returns a unique identifier for the topology. */ topologyId: Object;
} /** * Fired when the server monitor's ``hello`` or legacy hello command is started - immediately before * the ``hello`` or legacy hello command is serialized into raw BSON and written to the socket. * When the monitor is creating a new monitoring connection, this event is fired just before the * socket is opened. */
interface ServerHeartbeatStartedEvent { /** * Returns the connection id for the command. The connection id is the unique * identifier of the driver's Connection object that wraps the socket. For languages that * do not have this object, this MUST a string of "hostname:port" or an object that * that contains the hostname and port as attributes. * * The name of this field is flexible to match the object that is returned from the driver. * Examples are, but not limited to, 'address', 'serverAddress', 'connectionId', */ connectionId: ConnectionId; /** * Determines if this heartbeat event is for an awaitable ``hello`` or legacy hello. */ awaited: Boolean; } /** * Fired when the server monitor's ``hello`` or legacy hello succeeds. */
interface ServerHeartbeatSucceededEvent { /** * Returns the execution time of the event in the highest possible resolution for the platform. * The calculated value MUST be the time to send the message and receive the reply from the server, * including BSON serialization and deserialization. The name can imply the units in which the * value is returned, i.e. durationMS, durationNanos. * * When the awaited field is false, the time measurement used MUST be the * same measurement used for the RTT calculation. When the awaited field is * true, the time measurement is not used for RTT calculation. */ duration: Int64; /** * Returns the command reply. */ reply: Document; /** * Returns the connection id for the command. For languages that do not have this, * this MUST return the driver equivalent which MUST include the server address and port. * The name of this field is flexible to match the object that is returned from the driver. */ connectionId: ConnectionId; /** * Determines if this heartbeat event is for an awaitable ``hello`` or legacy hello. If * true, then the duration field cannot be used for RTT calculation * because the command blocks on the server. */ awaited: Boolean; } /** * Fired when the server monitor's ``hello`` or legacy hello fails, either with an "ok: 0" or a socket exception. */
interface ServerHeartbeatFailedEvent { /** * Returns the execution time of the event in the highest possible resolution for the platform. * The calculated value MUST be the time to send the message and receive the reply from the server, * including BSON serialization and deserialization. The name can imply the units in which the * value is returned, i.e. durationMS, durationNanos. */ duration: Int64; /** * Returns the failure. Based on the language, this SHOULD be a message string, * exception object, or error document. */ failure: String,Exception,Document; /** * Returns the connection id for the command. For languages that do not have this, * this MUST return the driver equivalent which MUST include the server address and port. * The name of this field is flexible to match the object that is returned from the driver. */ connectionId: ConnectionId; /** * Determines if this heartbeat event is for an awaitable ``hello`` or legacy hello. If * true, then the duration field cannot be used for RTT calculation * because the command blocks on the server. */ awaited: Boolean;
} The TopologyDescription object MUST expose the new methods defined in the API below, in order for subscribers to take action on certain conditions based on the driver options. TopologyDescription objects MAY have additional methods and properties. /** * Describes the current topology. */
interface TopologyDescription { /** * Determines if the topology has a readable server available. See the table in the * following section for behaviour rules. */ hasReadableServer(readPreference: Optional<ReadPreference>): Boolean /** * Determines if the topology has a writable server available. See the table in the * following section for behaviour rules. */ hasWritableServer(): Boolean
}

