All drivers that implement a connection pool MUST provide an API that allows users to subscribe to events emitted from the pool. If a user subscribes to Connection Monitoring events, these events MUST be emitted when specified in "Connection Pool Behaviors". Events SHOULD be created and subscribed to in a manner idiomatic to their language and driver. Events See the Load Balancer Specification for details on the serviceId field. /** * Emitted when a Connection Pool is created */
interface PoolCreatedEvent { /** * The ServerAddress of the Endpoint the pool is attempting to connect to. */ address: string; /** * Any non-default pool options that were set on this Connection Pool. */ options: {...}
} /** * Emitted when a Connection Pool is marked as ready. */
interface PoolReadyEvent { /** * The ServerAddress of the Endpoint the pool is attempting to connect to. */ address: string;
} /** * Emitted when a Connection Pool is cleared */
interface PoolClearedEvent { /** * The ServerAddress of the Endpoint the pool is attempting to connect to. */ address: string; /** * The service id for which the pool was cleared for in load balancing mode. * See load balancer specification for more information about this field. */ serviceId: Optional<ObjectId>; /** * A flag whether the pool forced interrupting "in use" connections as part of the clear. */ interruptInUseConnections: Optional<Boolean>;
} /** * Emitted when a Connection Pool is closed */
interface PoolClosedEvent { /** * The ServerAddress of the Endpoint the pool is attempting to connect to. */ address: string;
} /** * Emitted when a Connection Pool creates a Connection object. * NOTE: This does not mean that the Connection is ready for use. */
interface ConnectionCreatedEvent { /** * The ServerAddress of the Endpoint the pool is attempting to connect to. */ address: string; /** * The ID of the Connection */ connectionId: int64;
} /** * Emitted when a Connection has finished its setup, and is now ready to use */
interface ConnectionReadyEvent { /** * The ServerAddress of the Endpoint the pool is attempting to connect to. */ address: string; /** * The ID of the Connection */ connectionId: int64; /** * The time it took to establish the connection. * In accordance with the definition of establishment of a connection * specified by `ConnectionPoolOptions.maxConnecting`, * it is the time elapsed between emitting a `ConnectionCreatedEvent` * and emitting this event as part of the same checking out. * * Naturally, when establishing a connection is part of checking out, * this duration is not greater than * `ConnectionCheckedOutEvent`/`ConnectionCheckOutFailedEvent.duration`. * * A driver MAY choose the type idiomatic to the driver. * If the type chosen does not convey units, e.g., `int64`, * then the driver MAY include units in the name, e.g., `durationMS`. */ duration: Duration;
} /** * Emitted when a Connection Pool closes a Connection */
interface ConnectionClosedEvent { /** * The ServerAddress of the Endpoint the pool is attempting to connect to. */ address: string; /** * The ID of the Connection */ connectionId: int64; /** * A reason explaining why this Connection was closed. * Can be implemented as a string or enum. * Current valid values are: * - "stale": The pool was cleared, making the Connection no longer valid * - "idle": The Connection became stale by being available for too long * - "error": The Connection experienced an error, making it no longer valid * - "poolClosed": The pool was closed, making the Connection no longer valid */ reason: string|Enum;
} /** * Emitted when the driver starts attempting to check out a Connection */
interface ConnectionCheckOutStartedEvent { /** * The ServerAddress of the Endpoint the pool is attempting * to connect to. */ address: string;
} /** * Emitted when the driver's attempt to check out a Connection fails */
interface ConnectionCheckOutFailedEvent { /** * The ServerAddress of the Endpoint the pool is attempting to connect to. */ address: string; /** * A reason explaining why Connection check out failed. * Can be implemented as a string or enum. * Current valid values are: * - "poolClosed": The pool was previously closed, and cannot provide new Connections * - "timeout": The Connection check out attempt exceeded the specified timeout * - "connectionError": The Connection check out attempt experienced an error while setting up a new Connection */ reason: string|Enum; /** * See `ConnectionCheckedOutEvent.duration`. */ duration: Duration;
} /** * Emitted when the driver successfully checks out a Connection */
interface ConnectionCheckedOutEvent { /** * The ServerAddress of the Endpoint the pool is attempting to connect to. */ address: string; /** * The ID of the Connection */ connectionId: int64; /** * The time it took to check out the connection. * More specifically, the time elapsed between * emitting a `ConnectionCheckOutStartedEvent` * and emitting this event as part of the same checking out. * * Naturally, if a new connection was not created (`ConnectionCreatedEvent`) * and established (`ConnectionReadyEvent`) as part of checking out, * this duration is usually * not greater than `ConnectionPoolOptions.waitQueueTimeoutMS`, * but MAY occasionally be greater than that, * because a driver does not provide hard real-time guarantees. * * A driver MAY choose the type idiomatic to the driver. * If the type chosen does not convey units, e.g., `int64`, * then the driver MAY include units in the name, e.g., `durationMS`. */ duration: Duration;
} /** * Emitted when the driver checks in a Connection back to the Connection Pool */
interface ConnectionCheckedInEvent { /** * The ServerAddress of the Endpoint the pool is attempting to connect to. */ address: string; /** * The ID of the Connection */ connectionId: int64;
}

