A connection pool throws errors in specific circumstances. These Errors MUST be emitted by the pool. Errors SHOULD be created and dispatched in a manner idiomatic to the Driver and Language. /** * Thrown when the driver attempts to check out a * Connection from a closed Connection Pool */
interface PoolClosedError { message: 'Attempted to check out a Connection from closed connection pool'; address: <pool address>;
} /** * Thrown when the driver attempts to check out a * Connection from a paused Connection Pool */
interface PoolClearedError extends RetryableError { message: 'Connection pool for <pool address> was cleared because another operation failed with: <original error which cleared the pool>'; address: <pool address>;
} /** * Thrown when a driver times out when attempting to check out * a Connection from a Pool */
interface WaitQueueTimeoutError { message: 'Timed out while checking out a Connection from connection pool'; address: <pool address>;
}

