interface Collection { /** * This is a convenience method for creating a single index. This MUST call the * createIndexes method and pass the provided specification document in a * sequence to that method with the same options. * * @return The name of the created index. * * @note Drivers MAY opt to implement this method signature, the signature that * takes an IndexModel as a parameter, or for those languages with method * overloading MAY decide to implement both. * * @note Drivers MAY combine the two options types into a single one. If the options are * explicitly typed, the combined options type MUST be named CreateIndexOptions or an acceptable * variation. */ createIndex(keys: Document, indexOptions: Optional<IndexOptions>, options: Optional<CreateIndexOptions>): String; /** * @see Comments above. */ createIndex(model: IndexModel, options: Optional<CreateIndexOptions>): String /** * Creates multiple indexes in the collection. * * In all server versions, this MUST execute a createIndexes command. * * @return The names of all the indexes that were created. */ createIndexes(models: Iterable<IndexModel>, options: Optional<CreateIndexesOptions>): Iterable<String>; /** * Drops a single index from the collection by the index name. * * In all server versions this MUST execute a dropIndexes command. * * @note If the string passed is '*', the driver MUST raise an error since * more than one index would be dropped. */ dropIndex(name: String, options: Optional<DropIndexOptions>): Result; /** * Attempts to drop a single index from the collection given the keys and options. * * In all server versions this MUST execute a dropIndexes command. * * This is OPTIONAL until partial indexes are implemented. * * @note Drivers MAY opt to implement this method signature, the signature that * takes an IndexModel as a parameter, or for those languages with method * overloading MAY decide to implement both. * * @note Drivers MAY combine the two options types into a single one. If the options are * explicitly typed, the combined options type MUST be named DropIndexOptions or an acceptable * variation. */ dropIndex(keys: Document, indexOptions: IndexOptions, options: Optional<DropIndexOptions>): Result; /** * @see Comments above. */ dropIndex(model: IndexModel, options: Optional<DropIndexOptions>): Result; /** * Drops all indexes in the collection. */ dropIndexes(options: Optional<DropIndexesOptions>): Result; /** * Gets index information for all indexes in the collection. The behavior for * enumerating indexes is described in the :ref:`Enumerating Indexes` section. * */ listIndexes(options: Optional<ListIndexesOptions>): Cursor;
} interface CreateIndexOptions { /** * Specifies how many data-bearing members of a replica set, including the primary, must * complete the index builds successfully before the primary marks the indexes as ready. * * This option accepts the same values for the "w" field in a write concern plus "votingMembers", * which indicates all voting data-bearing nodes. * * This option is only supported by servers >= 4.4. Drivers MUST manually raise an error if this option * is specified when creating an index on a pre 4.4 server. See the Q&A section for the rationale behind this. * * @note This option is sent only if the caller explicitly provides a value. The default is to not send a value. * * @since MongoDB 4.4 */ commitQuorum: Optional<Int32 | String>; /** * The maximum amount of time to allow the index build to take before returning an error. * * @note This option is sent only if the caller explicitly provides a value. The default is to not send a value. */ maxTimeMS: Optional<Int64>; /** * Enables users to specify an arbitrary comment to help trace the operation through * the database profiler, currentOp and logs. The default is to not send a value. * * @see https://www.mongodb.com/docs/manual/reference/command/createIndexes/ * * @since MongoDB 4.4 */ comment: Optional<any>;
} interface CreateIndexesOptions { // same as CreateIndexOptions
} interface DropIndexOptions { /** * The maximum amount of time to allow the index drop to take before returning an error. * * @note This option is sent only if the caller explicitly provides a value. The default is to not send a value. */ maxTimeMS: Optional<Int64>; /** * Enables users to specify an arbitrary comment to help trace the operation through * the database profiler, currentOp and logs. The default is to not send a value. * * @see https://www.mongodb.com/docs/manual/reference/command/dropIndexes/ * * @since MongoDB 4.4 */ comment: Optional<any>;
} interface DropIndexesOptions { // same as DropIndexOptions
} Examples Create an index in a collection. Ruby: collection.create_index({ name: 1 }, { unique: true }) Java: collection.createIndex(new Document("name", 1), new IndexOptions().unique(true)); Produces the shell equivalent (>= 2.6.0) of: db.runCommand({ createIndexes: "users", indexes: [ { key: { name: 1 }, name: "name_1", unique: true } ]
}); Create multiple indexes in a collection. Ruby: collection.create_indexes([ { key: { name: 1 }, unique: true }, { key: { age: -1 }, name: "age" }
]) Java: collection.createIndexes(asList( new IndexModel(new Document("name", 1), new IndexOptions().unique(true)), new IndexModel(new Document("age", -1), new IndexOptions().name("age"))
)); Produces the shell equivalent (>= 2.6.0) of: db.runCommand({ createIndexes: "users", indexes: [ { key: { name: 1 }, name: "name_1", unique: true }, { key: { age: -1 }, name: "age" } ]
