interface IndexModel { /** * Contains the required keys for the index. */ keys: Document; /** * Contains the options for the index. */ options: IndexOptions;
} interface IndexOptions { /** * Optionally tells the server to build the index in the background and not block * other tasks. * * @note Starting in MongoDB 4.2, this option is ignored by the server. * @see https://www.mongodb.com/docs/manual/reference/command/createIndexes/ * @deprecated 4.2 */ background: Boolean; /** * Optionally specifies the length in time, in seconds, for documents to remain in * a collection. */ expireAfterSeconds: Int32; /** * Optionally specify a specific name for the index outside of the default generated * name. If none is provided then the name is generated in the format "[field]_[direction]". * * Note that if an index is created for the same key pattern with different collations, * a name must be provided by the user to avoid ambiguity. * * @example For an index of name: 1, age: -1, the generated name would be "name_1_age_-1". */ name: String; /** * Optionally tells the index to only reference documents with the specified field in * the index. */ sparse: Boolean; /** * Optionally used only in MongoDB 3.0.0 and higher. Allows users to configure the storage * engine on a per-index basis when creating an index. */ storageEngine: Document; /** * Optionally forces the index to be unique. */ unique: Boolean; /** * Optionally specifies the index version number, either 0 or 1. */ version: Int32; /** * Optionally specifies the default language for text indexes. * Is 'english' if none is provided. */ defaultLanguage: String; /** * Optionally Specifies the field in the document to override the language. */ languageOverride: String; /** * Optionally provides the text index version number. * * MongoDB 2.4 can only support version 1. * * MongoDB 2.6 and higher may support version 1 or 2. */ textIndexVersion: Int32; /** * Optionally specifies fields in the index and their corresponding weight values. */ weights: Document; /** * Optionally specifies the 2dsphere index version number. * * MongoDB 2.4 can only support version 1. * * MongoDB 2.6 and higher may support version 1 or 2. */ 2dsphereIndexVersion: Int32; /** * Optionally specifies the precision of the stored geo hash in the 2d index, from 1 to 32. */ bits: Int32; /** * Optionally sets the maximum boundary for latitude and longitude in the 2d index. */ max: Double; /** * Optionally sets the minimum boundary for latitude and longitude in the index in a * 2d index. */ min: Double; /** * Optionally specifies the number of units within which to group the location values * in a geo haystack index. */ bucketSize: Int32; /** * Optionally specifies a filter for use in a partial index. Only documents that match the * filter expression are included in the index. New in MongoDB 3.2. */ partialFilterExpression: Document; /** * Optionally specifies a collation to use for the index in MongoDB 3.4 and higher. * If not specified, no collation is sent and the default collation of the collection * server-side is used. */ collation: Document; /** * Optionally specifies the wildcard projection of a wildcard index. */ wildcardProjection: Document; /** * Optionally specifies that the index should exist on the target collection but should not be used by the query * planner when executing operations. * * This option is only supported by servers >= 4.4. */ hidden: Boolean; /** * Optionally specifies that this index is clustered. This is not a valid option to provide to * 'createIndexes', but can appear in the options returned for an index via 'listIndexes'. To * create a clustered index, create a new collection using the 'clusteredIndex' option. * * This options is only supported by servers >= 6.0. */ clustered: Boolean;
} interface ListIndexesOptions { /** * Enables users to specify an arbitrary comment to help trace the operation through * the database profiler, currentOp and logs. The default is to not send a value. * * If a comment is provided, drivers MUST attach this comment to all * subsequent getMore commands run on the same cursor. * * @see https://www.mongodb.com/docs/manual/reference/command/listIndexes/ * * @since MongoDB 4.4 */ comment: Optional<any>; /** * Configures the batch size of the cursor returned from the ``listIndexes`` command. * * @note drivers MAY chose to support batchSize on the ListIndexesOptions. */ batchSize: Optional<Int32>;
