Read [!NOTE] The term Iterable<T> is used below to indicate many of T. This spec is flexible on what that means as different drivers will have different requirements, types, and idioms. interface Collection { /** * Runs an aggregation framework pipeline. * * Note: $out and $merge are special pipeline stages that cause no results * to be returned from the server. As such, the iterable here would never * contain documents. Drivers MAY setup a cursor to be executed upon * iteration against the output collection such that if a user were to * iterate the return value, results would be returned. * * Note: result iteration should be backed by a cursor. Depending on the implementation, * the cursor may back the returned Iterable instance or an iterator that it produces. * * @see https://www.mongodb.com/docs/manual/reference/command/aggregate/ */ aggregate(pipeline: Document[], options: Optional<AggregateOptions>): Iterable<Document>; /** * Gets the number of documents matching the filter. * * **This method is DEPRECATED and should not be implemented in new drivers.** * * @see https://www.mongodb.com/docs/manual/reference/command/count/ @deprecated 4.0 */ count(filter: Document, options: Optional<CountOptions>): Int64; /** * Count the number of documents in a collection that match the given * filter. Note that an empty filter will force a scan of the entire * collection. For a fast count of the total documents in a collection * see estimatedDocumentCount. * * See "Count API Details" section below. */ countDocuments(filter: Document, options: Optional<CountOptions>): Int64; /** * Gets an estimate of the count of documents in a collection using collection metadata. * * See "Count API Details" section below for implementation and documentation * requirements. */ estimatedDocumentCount(options: Optional<EstimatedDocumentCountOptions>): Int64; /** * Finds the distinct values for a specified field across a single collection. * * Note: the results are backed by the "values" array in the distinct command's result * document. This differs from aggregate and find, where results are backed by a cursor. * * @see https://www.mongodb.com/docs/manual/reference/command/distinct/ */ distinct(fieldName: string, filter: Document, options: Optional<DistinctOptions>): Iterable<any>; /** * Finds the documents matching the model. * * Note: The filter parameter below equates to the $query meta operator. It cannot * contain other meta operators like $maxScan. However, do not validate this document * as it would be impossible to be forwards and backwards compatible. Let the server * handle the validation. * * Note: result iteration should be backed by a cursor. Depending on the implementation, * the cursor may back the returned Iterable instance or an iterator that it produces. * * @see https://www.mongodb.com/docs/manual/core/read-operations-introduction/ */ find(filter: Document, options: Optional<FindOptions>): Iterable<Document>; } interface Database { /** * Runs an aggregation framework pipeline on the database for pipeline stages * that do not require an underlying collection, such as $currentOp and $listLocalSessions. * * Note: result iteration should be backed by a cursor. Depending on the implementation, * the cursor may back the returned Iterable instance or an iterator that it produces. * * @see https://www.mongodb.com/docs/manual/reference/command/aggregate/#dbcmd.aggregate */ aggregate(pipeline: Document[], options: Optional<AggregateOptions>): Iterable<Document>; } class AggregateOptions { /** * Enables writing to temporary files. When set to true, aggregation stages * can write data to the _tmp subdirectory in the dbPath directory. * * This option is sent only if the caller explicitly provides a value. The default * is to not send a value. * * @see https://www.mongodb.com/docs/manual/reference/command/aggregate/ */ allowDiskUse: Optional<Boolean>; /** * The number of documents to return per batch. * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. * If specified, drivers SHOULD apply this option to both the original aggregate command and subsequent * getMore operations on the cursor. * * Drivers MUST NOT specify a batchSize of zero in an aggregate command that includes an $out or $merge stage, * as that will prevent the pipeline from executing. Drivers SHOULD leave the cursor.batchSize command option * unset in an aggregate command that includes an $out or $merge stage. * * @see https://www.mongodb.com/docs/manual/reference/command/aggregate/ */ batchSize: Optional<Int32>; /** * If true, allows the write to opt-out of document level validation. This only applies * when the $out or $merge stage is specified. * * This option is sent only if the caller explicitly provides a true value. The default is to not send a value. * For servers < 3.2, this option is ignored and not sent as document validation is not available. * * @see https://www.mongodb.com/docs/manual/reference/command/aggregate/ */ bypassDocumentValidation: Optional<Boolean>; /** * Specifies a collation. * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. * For servers < 3.4, the driver MUST raise an error if the caller explicitly provides a value. * * @see https://www.mongodb.com/docs/manual/reference/command/aggregate/ */ collation: Optional<Document>; /** * The maximum amount of time to allow the query to run. * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. * * NOTE: This option is deprecated in favor of timeoutMS. * * @see https://www.mongodb.com/docs/manual/reference/command/aggregate/ */ maxTimeMS: Optional<Int64>; /** * The maximum amount of time for the server to wait on new documents to satisfy a tailable cursor * query. * * This options only applies to aggregations which return a TAILABLE_AWAIT cursor. Drivers * SHOULD always send this value, if the cursor is not a TAILABLE_AWAIT cursor the server will * ignore it. * * @note this option is an alias for maxTimeMS, used on getMore commands * @note this option is not set on the aggregate command */ maxAwaitTimeMS: Optional<Int64>; /** * Enables users to specify an arbitrary comment to help trace the operation through * the database profiler, currentOp and logs. The default is to not send a value. * * The comment can be any valid BSON type for server versions 4.4 and above. * Server versions between 3.6 and 4.2 only support string as comment, * and providing a non-string type will result in a server-side error. * Older server versions do not support comment for aggregate command at all, * and providing one will result in a server-side error. * * If a comment is provided, drivers MUST attach this comment to all * subsequent getMore commands run on the same cursor for server * versions 4.4 and above. For server versions below 4.4 drivers MUST NOT * attach a comment to getMore commands. */ comment: Optional<any>; /** * The index to use for the aggregation. The hint does not apply to $lookup and $graphLookup stages. * Specify either the index name as a string or the index key pattern. If specified, * then the query system will only consider plans using the hinted index. * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. * * @see https://www.mongodb.com/docs/manual/reference/command/aggregate/ */ hint: Optional<(String | Document)>; /** * Map of parameter names and values. Values must be constant or closed * expressions that do not reference document fields. Parameters can then be * accessed as variables in an aggregate expression context (e.g. "$$var"). * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. * This option is only supported by servers >= 5.0. Older servers >= 2.6 (and possibly earlier) will report an error for using this option. * * @see https://www.mongodb.com/docs/manual/reference/command/aggregate/ */ let: Optional<Document>;
} class CountOptions { /** * Specifies a collation. * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. * For servers < 3.4, the driver MUST raise an error if the caller explicitly provides a value. */ collation: Optional<Document>; /** * The index to use. Specify either the index name as a string or the index key pattern. * If specified, then the query system will only consider plans using the hinted index. * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. */ hint: Optional<(String | Document)>; /** * The maximum number of documents to count. * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. */ limit: Optional<Int64>; /** * The maximum amount of time to allow the operation to run. * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. * * NOTE: This option is deprecated in favor of timeoutMS. */ maxTimeMS: Optional<Int64>; /** * The number of documents to skip before counting. * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. */ skip: Optional<Int64>; /** * Enables users to specify an arbitrary comment to help trace the operation through * the database profiler, currentOp and logs. The default is to not send a value. * * The comment can be any valid BSON type for server versions 4.4 and above. * Server versions prior to 4.4 do not support comment for count command, * and providing one will result in a server-side error. */ comment: Optional<any>;
} class EstimatedDocumentCountOptions { /** * The maximum amount of time to allow the operation to run. * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. * * NOTE: This option is deprecated in favor of timeoutMS. */ maxTimeMS: Optional<Int64>; /** * Enables users to specify an arbitrary comment to help trace the operation through * the database profiler, currentOp and logs. The default is to not send a value. * * The comment can be any valid BSON type for server versions 4.4.14 and above. * For server versions between 4.4.0 and 4.4.14 string comment is supported. * Servers versions below 4.4.0 do not support comment for count command, * which is used to implement estimatedDocumentCount. Therefore, providing a * comment may result in a server-side error. */ comment: Optional<any>;
} class DistinctOptions { /** * Specifies a collation. * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. * For servers < 3.4, the driver MUST raise an error if the caller explicitly provides a value. * * @see https://www.mongodb.com/docs/manual/reference/command/distinct/ */ collation: Optional<Document>; /** * The maximum amount of time to allow the query to run. * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. * * NOTE: This option is deprecated in favor of timeoutMS. * * @see https://www.mongodb.com/docs/manual/reference/command/distinct/ */ maxTimeMS: Optional<Int64>; /** * Enables users to specify an arbitrary comment to help trace the operation through * the database profiler, currentOp and logs. The default is to not send a value. * * The comment can be any valid BSON type for server versions 4.4 and above. * Server versions prior to 4.4 do not support comment for distinct command, * and providing one will result in a server-side error. */ comment: Optional<any>;
} enum CursorType { /** * The default value. A vast majority of cursors will be of this type. */ NON_TAILABLE, /** * Tailable means the cursor is not closed when the last data is retrieved. * Rather, the cursor marks the final object’s position. You can resume * using the cursor later, from where it was located, if more data were * received. Like any "latent cursor", the cursor may become invalid at * some point (CursorNotFound) – for example if the final object it * references were deleted. * * @see https://www.mongodb.com/docs/meta-driver/latest/legacy/mongodb-wire-protocol/#op-query */ TAILABLE, /** * Combines the tailable option with awaitData, as defined below. * * Use with TailableCursor. If we are at the end of the data, block for a * while rather than returning no data. After a timeout period, we do return * as normal. The default is true. * * @see https://www.mongodb.com/docs/meta-driver/latest/legacy/mongodb-wire-protocol/#op-query */ TAILABLE_AWAIT
} class FindOptions { /** * Enables writing to temporary files on the server. When set to true, the server * can write temporary data to disk while executing the find operation. * * This option is sent only if the caller explicitly provides a value. The default * is to not send a value. * * This option is only supported by servers >= 4.4. Older servers >= 3.2 will report an error for using this option. * For servers < 3.2, the driver MUST raise an error if the caller explicitly provides a value. * * @see https://www.mongodb.com/docs/manual/reference/command/find/ */ allowDiskUse: Optional<Boolean>; /** * Get partial results from a mongos if some shards are down (instead of throwing an error). * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. * For servers < 3.2, the Partial wire protocol flag is used and defaults to false. * * @see https://www.mongodb.com/docs/manual/reference/command/find/ */ allowPartialResults: Optional<Boolean>; /** * The number of documents to return per batch. * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. * For servers < 3.2, this is combined with limit to create the wire protocol numberToReturn value. * If specified, drivers SHOULD apply this option to both the original query operation and subsequent * getMore operations on the cursor. * * @see https://www.mongodb.com/docs/manual/reference/command/find/ */ batchSize: Optional<Int32>; /** * Specifies a collation. * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. * For servers < 3.4, the driver MUST raise an error if the caller explicitly provides a value. * * @see https://www.mongodb.com/docs/manual/reference/command/find/ */ collation: Optional<Document>; /** * Enables users to specify an arbitrary comment to help trace the operation through * the database profiler, currentOp and logs. The default is to not send a value. * * The comment can be any valid BSON type for server versions 4.4 and above. * Server versions prior to 4.4 only support string as comment, * and providing a non-string type will result in a server-side error. * * If a comment is provided, drivers MUST attach this comment to all * subsequent getMore commands run on the same cursor for server * versions 4.4 and above. For server versions below 4.4 drivers MUST NOT * attach a comment to getMore commands. */ comment: Optional<any>; /** * Indicates the type of cursor to use. This value includes both * the tailable and awaitData options. * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. * For servers < 3.2, the AwaitData and Tailable wire protocol flags are used and default to false. * * @see https://www.mongodb.com/docs/manual/reference/command/find/ */ cursorType: Optional<CursorType>; /** * The index to use. Specify either the index name as a string or the index key pattern. * If specified, then the query system will only consider plans using the hinted index. * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. * * @see https://www.mongodb.com/docs/manual/reference/command/find/ */ hint: Optional<(String | Document)>; /** * The maximum number of documents to return. * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. * For servers < 3.2, this is combined with batchSize to create the wire protocol numberToReturn value. * * A negative limit implies that the caller has requested a single batch of results. For servers >= 3.2, singleBatch * should be set to true and limit should be converted to a positive value. For servers < 3.2, the wire protocol * numberToReturn value may be negative. * * @see https://www.mongodb.com/docs/manual/reference/command/find/ */ limit: Optional<Int64>; /** * The exclusive upper bound for a specific index. * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. * * @see https://www.mongodb.com/docs/manual/reference/command/find/ */ max: Optional<Document>; /** * The maximum amount of time for the server to wait on new documents to satisfy a tailable cursor * query. This only applies to a TAILABLE_AWAIT cursor. When the cursor is not a TAILABLE_AWAIT cursor, * this option is ignored. * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. * For servers < 3.2, this option is ignored and not sent as maxTimeMS does not exist in the OP_GET_MORE wire protocol. * * Note: This option is specified as "maxTimeMS" in the getMore command and not provided as part of the * initial find command. * * @see https://www.mongodb.com/docs/manual/reference/command/find/ */ maxAwaitTimeMS: Optional<Int64>; /** * Maximum number of documents or index keys to scan when executing the query. * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. * * @see https://www.mongodb.com/docs/manual/reference/command/find/ * @deprecated 4.0 */ maxScan: Optional<Int64>; /** * The maximum amount of time to allow the query to run. * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. * * NOTE: This option is deprecated in favor of timeoutMS. * * @see https://www.mongodb.com/docs/manual/reference/command/find/ */ maxTimeMS: Optional<Int64>; /** * The inclusive lower bound for a specific index. * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. * * @see https://www.mongodb.com/docs/manual/reference/command/find/ */ min: Optional<Document>; /** * The server normally times out idle cursors after an inactivity period (10 minutes) * to prevent excess memory use. Set this option to prevent that. * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. * For servers < 3.2, the NoCursorTimeout wire protocol flag is used and defaults to false. * * @see https://www.mongodb.com/docs/manual/reference/command/find/ */ noCursorTimeout: Optional<Boolean>; /** * Enables optimization when querying the oplog for a range of ts values * * Note: this option is intended for internal replication use only. * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. * For servers < 3.2, the OplogReplay wire protocol flag is used and defaults to false. * For servers >= 4.4, the server will ignore this option if set (see: SERVER-36186). * * @see https://www.mongodb.com/docs/manual/reference/command/find/ * @deprecated 4.4 */ oplogReplay: Optional<Boolean>; /** * Limits the fields to return for all matching documents. * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. * * @see https://www.mongodb.com/docs/manual/reference/command/find/ */ projection: Optional<Document>; /** * If true, returns only the index keys in the resulting documents. * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. * * @see https://www.mongodb.com/docs/manual/reference/command/find/ */ returnKey: Optional<Boolean>; /** * Determines whether to return the record identifier for each document. If true, adds a field $recordId to the returned documents. * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. * * @see https://www.mongodb.com/docs/manual/reference/command/find/ */ showRecordId: Optional<Boolean>; /** * The number of documents to skip before returning. * * This option is sent only if the caller explicitly provides a value. The default is to not send a value. * For servers < 3.2, this is a wire protocol parameter that defaults to 0. * * @see https://www.mongodb.com/docs/manual/reference/command/find/ */ skip: