A WriteModel defines a single write operation to be performed as part of a bulk write. /** * Unifying interface for the various write model types. Drivers may also use an enum with * variants for each write model for this type. */
interface WriteModel {} class InsertOneModel implements WriteModel { /** * The document to insert. */ document: Document;
} class UpdateOneModel implements WriteModel { /** * The filter to apply. */ filter: Document; /** * The update document or pipeline to apply to the selected document. */ update: (Document | Document[]); /** * A set of filters specifying to which array elements an update should apply. * * This option is sent only if the caller explicitly provides a value. */ arrayFilters: Optional<Document[]>; /** * Specifies a collation. * * This option is sent only if the caller explicitly provides a value. */ collation: Optional<Document>; /** * The index to use. Specify either the index name as a string or the index key pattern. If * specified, then the query system will only consider plans using the hinted index. * * This option is only sent if the caller explicitly provides a value. */ hint: Optional<Document | String>; /** * When true, creates a new document if no document matches the query. * * This option is only sent if the caller explicitly provides a value. The server's default * value is false. */ upsert: Optional<Boolean>; /** * Specify which document the operation updates if the query matches multiple * documents. The first document matched by the sort order will be updated. * * This option is only sent if the caller explicitly provides a value. */ sort: Optional<Document>;
} class UpdateManyModel implements WriteModel { /** * The filter to apply. */ filter: Document; /** * The update document or pipeline to apply to the selected documents. */ update: (Document | Document[]); /** * A set of filters specifying to which array elements an update should apply. * * This option is sent only if the caller explicitly provides a value. */ arrayFilters: Optional<Document[]>; /** * Specifies a collation. * * This option is sent only if the caller explicitly provides a value. */ collation: Optional<Document>; /** * The index to use. Specify either the index name as a string or the index key pattern. If * specified, then the query system will only consider plans using the hinted index. * * This option is only sent if the caller explicitly provides a value. */ hint: Optional<Document | String>; /** * When true, creates a new document if no document matches the query. * * This option is only sent if the caller explicitly provides a value. The server's default * value is false. */ upsert: Optional<Boolean>;
} class ReplaceOneModel implements WriteModel { /** * The filter to apply. */ filter: Document; /** * The replacement document. */ replacement: Document; /** * Specifies a collation. * * This option is sent only if the caller explicitly provides a value. */ collation: Optional<Document>; /** * The index to use. Specify either the index name as a string or the index key pattern. If * specified, then the query system will only consider plans using the hinted index. * * This option is only sent if the caller explicitly provides a value. */ hint: Optional<Document | String>; /** * When true, creates a new document if no document matches the query. * * This option is only sent if the caller explicitly provides a value. The server's default * value is false. */ upsert: Optional<Boolean>; /** * Specify which document the operation replaces if the query matches multiple * documents. The first document matched by the sort order will be replaced. * * This option is only sent if the caller explicitly provides a value. */ sort: Optional<Document>;
} class DeleteOneModel implements WriteModel { /** * The filter to apply. */ filter: Document; /** * Specifies a collation. * * This option is sent only if the caller explicitly provides a value. */ collation: Optional<Document>; /** * The index to use. Specify either the index name as a string or the index key pattern. If * specified, then the query system will only consider plans using the hinted index. * * This option is only sent if the caller explicitly provides a value. */ hint: Optional<Document | String>;
} class DeleteManyModel implements WriteModel { /** * The filter to apply. */ filter: Document; /** * Specifies a collation. * * This option is sent only if the caller explicitly provides a value. */ collation: Optional<Document>; /** * The index to use. Specify either the index name as a string or the index key pattern. If * specified, then the query system will only consider plans using the hinted index. * * This option is only sent if the caller explicitly provides a value. */ hint: Optional<Document | String>;
} Each write model provided to MongoClient.bulkWrite in the models parameter MUST have a corresponding namespace that defines the collection on which the operation should be performed. Drivers SHOULD design this pairing in whichever way is most idiomatic for its language. For example, drivers may: Include a required namespace field on each WriteModel variant and accept a list of WriteModel objects for the models parameter. Accept a list of (Namespace, WriteModel) tuples for models. Define the following pair class: class NamespaceWriteModelPair { /** * The namespace on which to perform the write. */ namespace: Namespace; /** * The write to perform. */ model: WriteModel;
} Drivers MUST throw an exception if the list provided for models is empty. Update vs. replace document validation Update documents provided in UpdateOne and UpdateMany write models are required only to contain atomic modifiers (i.e. keys that start with $). Drivers MUST throw an error if an update document is empty or if the document's first key does not start with $. Drivers MUST rely on the server to return an error if any other entries in the update document are not atomic modifiers. Drivers are not required to perform validation on update pipelines. Replacement documents provided in ReplaceOne write models are required not to contain atomic modifiers. Drivers MUST throw an error if a replacement document is nonempty and its first key starts with $. Drivers MUST rely on the server to return an error if any other entries in the replacement document are atomic modifiers.

