interface ChangeStream extends Iterable<Document> { /** * The cached resume token */ private resumeToken: Document; /** * The pipeline of stages to append to an initial ``$changeStream`` stage */ private pipeline: Array<Document>; /** * The options provided to the initial ``$changeStream`` stage */ private options: ChangeStreamOptions; /** * The read preference for the initial change stream aggregation, used * for server selection during an automatic resume. */ private readPreference: ReadPreference;
} interface Collection { /** * @returns a change stream on a specific collection. */ watch(pipeline: Document[], options: Optional<ChangeStreamOptions>): ChangeStream;
} interface Database { /** * Allows a client to observe all changes in a database. * Excludes system collections. * @returns a change stream on all collections in a database * @since 4.0 * @see https://www.mongodb.com/docs/manual/reference/system-collections/ */ watch(pipeline: Document[], options: Optional<ChangeStreamOptions>): ChangeStream;
} interface MongoClient { /** * Allows a client to observe all changes in a cluster. * Excludes system collections. * Excludes the "config", "local", and "admin" databases. * @since 4.0 * @returns a change stream on all collections in all databases in a cluster * @see https://www.mongodb.com/docs/manual/reference/system-collections/ */ watch(pipeline: Document[], options: Optional<ChangeStreamOptions>): ChangeStream;
} class ChangeStreamOptions { /** * Allowed values: 'default', 'updateLookup', 'whenAvailable', 'required'. * * The default is to not send a value, which is equivalent to 'default'. By * default, the change notification for partial updates will include a delta * describing the changes to the document. * * When set to 'updateLookup', the change notification for partial updates * will include both a delta describing the changes to the document as well * as a copy of the entire document that was changed from some time after * the change occurred. * * When set to 'whenAvailable', configures the change stream to return the * post-image of the modified document for replace and update change events * if the post-image for this event is available. * * When set to 'required', the same behavior as 'whenAvailable' except that * an error is raised if the post-image is not available. * * For forward compatibility, a driver MUST NOT raise an error when a user * provides an unknown value. The driver relies on the server to validate * this option. * * @note this is an option of the `$changeStream` pipeline stage. */ fullDocument: Optional<String>; /** * Allowed values: 'whenAvailable', 'required', 'off'. * * The default is to not send a value, which is equivalent to 'off'. * * When set to 'whenAvailable', configures the change stream to return the * pre-image of the modified document for replace, update, and delete change * events if it is available. * * When set to 'required', the same behavior as 'whenAvailable' except that * an error is raised if the pre-image is not available. * * For forward compatibility, a driver MUST NOT raise an error when a user * provides an unknown value. The driver relies on the server to validate * this option. * * @note this is an option of the `$changeStream` pipeline stage. */ fullDocumentBeforeChange: Optional<String>; /** * Specifies the logical starting point for the new change stream. * * @note this is an option of the `$changeStream` pipeline stage. */ resumeAfter: Optional<Document>; /** * The maximum amount of time for the server to wait on new documents to satisfy * a change stream query. * * This is the same field described in FindOptions in the CRUD spec. * * @see https://github.com/mongodb/specifications/blob/master/source/crud/crud.md#read * @note this option is an alias for `maxTimeMS`, used on `getMore` commands * @note this option is not set on the `aggregate` command nor `$changeStream` pipeline stage */ maxAwaitTimeMS: Optional<Int64>; /** * The number of documents to return per batch. * * This option is sent only if the caller explicitly provides a value. The * default is to not send a value. * * @see https://www.mongodb.com/docs/manual/reference/command/aggregate * @note this is an aggregation command option */ batchSize: Optional<Int32>; /** * Specifies a collation. * * This option is sent only if the caller explicitly provides a value. The * default is to not send a value. * * @see https://www.mongodb.com/docs/manual/reference/command/aggregate * @note this is an aggregation command option */ collation: Optional<Document>; /** * The change stream will only provide changes that occurred at or after the * specified timestamp. Any command run against the server will return * an operation time that can be used here. * * @since 4.0 * @see https://www.mongodb.com/docs/manual/reference/method/db.runCommand/ * @note this is an option of the `$changeStream` pipeline stage. */ startAtOperationTime: Optional<Timestamp>; /** * Similar to `resumeAfter`, this option takes a resume token and starts a * new change stream returning the first notification after the token. * This will allow users to watch collections that have been dropped and recreated * or newly renamed collections without missing any notifications. * * The server will report an error if `startAfter` and `resumeAfter` are both specified. * * @since 4.1.1 * @see https://www.mongodb.com/docs/manual/changeStreams/#change-stream-start-after * @note this is an option of the `$changeStream` pipeline stage. */ startAfter: Optional<Document>; /** * Enables users to specify an arbitrary comment to help trace the operation through * the database profiler, currentOp and logs. The default is to not send a value. * * The comment can be any valid BSON type for server versions 4.4 and above. * Server versions prior to 4.4 only support string as comment, * and providing a non-string type will result in a server-side error. * * If a comment is provided, drivers MUST attach this comment to all * subsequent getMore commands run on the same cursor for server * versions 4.4 and above. For server versions below 4.4 drivers MUST NOT * attach a comment to getMore commands. * * @see https://www.mongodb.com/docs/manual/reference/command/aggregate * @note this is an aggregation command option */ comment: Optional<any> /** * Enables the server to send the 'expanded' list of change stream events. * The list of additional events included with this flag set are * - createIndexes * - dropIndexes * - modify * - create * - shardCollection * - reshardCollection * - refineCollectionShardKey * * This flag is available in server versions greater than 6.0.0. `reshardCollection` and * `refineCollectionShardKey` events are not available until server version 6.1.0. * * @note this is an option of the change stream pipeline stage */ showExpandedEvents: Optional<Boolean>
} NOTE: The set of ChangeStreamOptions may grow over time. Helper Method The driver API consists of a ChangeStream type, as well as three helper methods. All helpers MUST return a ChangeStream instance. Implementers MUST document that helper methods are preferred to running a raw aggregation with a $changeStream stage, for the purpose of supporting resumability. The helper methods must construct an aggregation command with a REQUIRED initial $changeStream stage. A driver MUST NOT throw a custom exception if multiple $changeStream stages are present (e.g. if a user also passed $changeStream in the pipeline supplied to the helper), as the server will return an error. The helper methods MUST determine a read concern for the operation in accordance with the Read and Write Concern specification . The initial implementation of change streams on the server requires a 'majority' read concern or no read concern. Drivers MUST document this requirement. Drivers SHALL NOT throw an exception if any other read concern is specified, but instead should depend on the server to return an error. The stage has the following shape: { $changeStream: ChangeStreamOptions } The first parameter of the helpers specifies an array of aggregation pipeline stages which MUST be appended to the initial stage. Drivers MUST support an empty pipeline. Languages which support default parameters MAY specify an empty array as the default value for this parameter. Drivers SHOULD otherwise make specification of a pipeline as similar as possible to the aggregate CRUD method. Additionally, implementers MAY provide a form of these methods which require no parameters, assuming no options and no additional stages beyond the initial $changeStream stage: for change in db.collection.watch(): print(change) Presently change streams support only a subset of available aggregation stages: $match $project $addFields $replaceRoot $redact A driver MUST NOT throw an exception if any unsupported stage is provided, but instead depend on the server to return an error. A driver MUST NOT throw an exception if a user adds, removes, or modifies fields using $project. The server will produce an error if _id is projected out, but a user should otherwise be able to modify the shape of the change stream event as desired. This may require the result to be deserialized to a BsonDocument or custom-defined type rather than a ChangeStreamDocument. It is the responsibility of the user to ensure that the deserialized type is compatible with the specified $project stage. The aggregate helper methods MUST have no new logic related to the $changeStream stage. Drivers MUST be capable of handling TAILABLE_AWAIT cursors from the aggregate command in the same way they handle such cursors from find. Collection.watch helper Returns a ChangeStream on a specific collection Command syntax: { aggregate: 'collectionName' pipeline: [{$changeStream: {...}}, ...], ...
} Database.watch helper Since: 4.0 Returns a ChangeStream on all collections in a database. Command syntax: { aggregate: 1 pipeline: [{$changeStream: {...}}, ...], ...
} Drivers MUST use the ns returned in the aggregate command to set the collection option in subsequent getMore commands. MongoClient.watch helper Since: 4.0 Returns a ChangeStream on all collections in all databases in a cluster Command syntax: { aggregate: 1 pipeline: [{$changeStream: {allChangesForCluster: true, ...}}, ...], ...
} The helper MUST run the command against the admin database Drivers MUST use the ns returned in the aggregate command to set the collection option in subsequent getMore commands. ChangeStream A ChangeStream is an abstraction of a TAILABLE_AWAIT cursor, with support for resumability. Implementers MAY choose to implement a ChangeStream as an extension of an existing tailable cursor implementation. If the ChangeStream is implemented as a type which owns a tailable cursor, then the implementer MUST provide a manner of closing the change stream, as well as satisfy the requirements of extending Iterable<Document>. If your language has an idiomatic way of disposing of resources you MAY choose to implement that in addition to, or instead of, an explicit close method. A change stream MUST track the last resume token, per Updating the Cached Resume Token . Drivers MUST raise an error on the first document received without a resume token (e.g. the user has removed _id with a pipeline stage), and close the change stream. The error message SHOULD resemble "Cannot provide resume functionality when the resume token is missing". A change stream MUST attempt to resume a single time if it encounters any resumable error per Resumable Error . A change stream MUST NOT attempt to resume on any other type of error. In addition to tracking a resume token, change streams MUST also track the read preference specified when the change stream was created. In the event of a resumable error, a change stream MUST perform server selection with the original read preference using the rules for server selection before attempting to resume. Single Server Topologies Presently, change streams cannot be initiated on single server topologies as they do not have an oplog. Drivers MUST NOT throw an exception in this scenario, but instead rely on an error returned from the server. This allows for the server to seamlessly introduce support for this in the future, without need to make changes in driver code. startAtOperationTime Since: 4.0 startAtOperationTime specifies that a change stream will only return changes that occurred at or after the specified Timestamp. The server expects startAtOperationTime as a BSON Timestamp. Drivers MUST allow users to specify a startAtOperationTime option in the watch helpers. They MUST allow users to specify this value as a raw Timestamp. startAtOperationTime, resumeAfter, and startAfter are all mutually exclusive; if any two are set, the server will return an error. Drivers MUST NOT throw a custom error, and MUST defer to the server error. The ChangeStream MUST save the operationTime from the initial aggregate response when the following criteria are met: None of startAtOperationTime, resumeAfter, startAfter were specified in the ChangeStreamOptions. The max wire version is >= 7. The initial aggregate response had no results. The initial aggregate response did not include a postBatchResumeToken. resumeAfter resumeAfter is used to resume a ChangeStream that has been stopped to ensure that only changes starting with the log entry immediately after the provided token will be returned. If the resume token specified does not exist, the server will return an error. Resume Process Once a ChangeStream has encountered a resumable error, it MUST attempt to resume one time. The process for resuming MUST follow these steps: Perform server selection. Connect to selected server. If there is a cached resumeToken: If the ChangeStream was started with startAfter and has yet to return a result document: The driver MUST set startAfter to the cached resumeToken. The driver MUST NOT set resumeAfter. The driver MUST NOT set startAtOperationTime. If startAtOperationTime was in the original aggregation command, the driver MUST remove it. Else: The driver MUST set resumeAfter to the cached resumeToken. The driver MUST NOT set startAfter. If startAfter was in the original aggregation command, the driver MUST remove it. The driver MUST NOT set startAtOperationTime. If startAtOperationTime was in the original aggregation command, the driver MUST remove it. Else if there is no cached resumeToken and the ChangeStream has a saved operation time (either from an originally specified startAtOperationTime or saved from the original aggregation) and the max wire version is >= 7: The driver MUST NOT set resumeAfter. The driver MUST NOT set startAfter. The driver MUST set startAtOperationTime to the value of the originally used startAtOperationTime or the one saved from the original aggregation. Else: The driver MUST NOT set resumeAfter, startAfter, or startAtOperationTime. The driver MUST use the original aggregation command to resume. When resumeAfter is specified the ChangeStream will return notifications starting with the oplog entry immediately after the provided token. If the server supports sessions, the resume attempt MUST use the same session as the previous attempt's command. A driver MUST ensure that consecutive resume attempts can succeed, even in the absence of any changes received by the cursor between resume attempts. A driver SHOULD attempt to kill the cursor on the server on which the cursor is opened during the resume process, and MUST NOT attempt to kill the cursor on any other server. Any exceptions or errors that occur during the process of killing the cursor should be suppressed, including both errors returned by the killCursor command and exceptions thrown by opening, writing to, or reading from the socket. Exposing All Resume Tokens Since: 4.0.7 Users can inspect the _id on each ChangeDocument to use as a resume token. But since MongoDB 4.0.7, aggregate and getMore responses also include a postBatchResumeToken. Drivers use one or the other when automatically resuming, as described in Resume Process . Drivers MUST expose a mechanism to retrieve the same resume token that would be used to automatically resume. It MUST be possible to use this mechanism after iterating every document. It MUST be possible for users to use this mechanism periodically even when no documents are getting returned (i.e. getMore has returned empty batches). Drivers have two options to implement this. Option 1: ChangeStream::getResumeToken() interface ChangeStream extends Iterable<Document> { /** * Returns the cached resume token that will be used to resume * after the most recently returned change. */ public getResumeToken() Optional<Document>;
} This MUST be implemented in synchronous drivers. This MAY be implemented in asynchronous drivers. Option 2: Event Emitted for Resume Token Allow users to set a callback to listen for new resume tokens. The exact interface is up to the driver, but it MUST meet the following criteria: The callback is set in the same manner as a callback used for receiving change documents. The callback accepts a resume token as an argument. The callback (or event) MAY include an optional ChangeDocument, which is unset when called with resume tokens sourced from postBatchResumeToken. A possible interface for this callback MAY look like: interface ChangeStream extends Iterable<Document> { /** * Returns a resume token that should be used to resume after the most * recently returned change. */ public onResumeTokenChanged(ResumeTokenCallback:(Document resumeToken) => void);
} This MUST NOT be implemented in synchronous drivers. This MAY be implemented in asynchronous drivers. Updating the Cached Resume Token The following rules describe how to update the cached resumeToken: When the ChangeStream is started: If startAfter is set, cache it. Else if resumeAfter is set, cache it. Else, resumeToken remains unset. When aggregate or getMore returns: If an empty batch was returned and a postBatchResumeToken was included, cache it. When returning a document to the user: If it's the last document in the batch and a postBatchResumeToken is included, cache it. Else, cache the _id of the document. Not Blocking on Iteration Synchronous drivers MUST provide a way to iterate a change stream without blocking until a change document is returned. This MUST give the user an opportunity to get the most up-to-date resume token, even when the change stream continues to receive empty batches in getMore responses. This allows users to call ChangeStream::getResumeToken() after iterating every document and periodically when no documents are getting returned. Although the implementation of tailable awaitData cursors is not specified, this MAY be implemented with a tryNext method on the change stream cursor. All drivers MUST document how users can iterate a change stream and receive all resume token updates. Why do we allow access to the resume token to users shows an example. The documentation MUST state that users intending to store the resume token should use this method to get the most up to date resume token. Timeouts Drivers MUST apply timeouts to change stream establishment, iteration, and resume attempts per Client Side Operations Timeout: Change Streams . Notes and Restrictions 1. fullDocument: updateLookup can result in change documents larger than 16 MiB There is a risk that if there is a large change to a large document, the full document and delta might result in a document larger than the 16 MiB limitation on BSON documents. If that happens the cursor will be closed, and a server error will be returned. 2. Users can remove the resume token with aggregation stages It is possible for a user to specify the following stage: { $project: { _id: 0 } } Similar removal of the resume token is possible with the $redact and $replaceRoot stages. While this is not technically illegal, it makes it impossible for drivers to support resumability. Users may explicitly opt out of resumability by issuing a raw aggregation with a $changeStream stage.
